}

// ===== ROUTING =====
function navigate(page) {
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  const target = document.getElementById('page-' + page);
  if (target) {
    target.classList.add('active');
    window.scrollTo(0, 0);
  }
  currentPage = page;
  // Update nav active
  document.querySelectorAll('.nav-links a, .mobile-menu a').forEach(a => {
    a.classList.toggle('active', a.dataset.page === page);
  });
  // Update hash
  history.replaceState(null, '', '#' + page);
  // Trigger animations
  setTimeout(observeFadeUps, 50);
  // Reset carousel if beliefs
  if (page === 'beliefs') {
    carouselIndex = 0;
    updateCarousel();
    startCarouselTimer();
  }
  // Gallery: static timeline, no build needed
  if (page === 'gallery') { setTimeout(observeFadeUps, 100); }
}

function handleHash() {
  const hash = window.location.hash.replace('#', '') || 'home';
  const valid = ['home','legend','club','beliefs','gallery','trail','quotes','testimonials','vision'];
  navigate(valid.includes(hash) ? hash : 'home');
}

// Nav link clicks
document.querySelectorAll('[data-page]').forEach(el => {
  el.addEventListener('click', function(e) {
    e.preventDefault();
    navigate(this.dataset.page);
  });
});

window.addEventListener('hashchange', handleHash);
window.addEventListener('load', handleHash);

// ===== LANGUAGE TOGGLE =====
function toggleLang() {
  currentLang = currentLang === 'zh' ? 'en' : 'zh';
  const btn = document.getElementById('langToggle');
  const mBtn = document.getElementById('mobileLangBtn');
  btn.textContent = currentLang === 'zh' ? 'EN' : '中';
  if (mBtn) mBtn.textContent = currentLang === 'zh' ? '切換 EN' : '切換 中';
  document.querySelectorAll('[data-i18n]').forEach(el => {
    if (currentLang === 'en') {
      const enText = el.getAttribute('data-i18n-en');
      if (enText) el.textContent = enText;
    } else {
      const zhText = el.getAttribute('data-i18n');
      if (zhText) el.textContent = zhText;
    }
  });
  document.documentElement.lang = currentLang === 'zh' ? 'zh-TW' : 'en';
}

// ===== HAMBURGER =====
function toggleMenu() {
  const menu = document.getElementById('mobileMenu');
  const btn = document.getElementById('hamburger');
  menu.classList.toggle('open');
  btn.classList.toggle('open');
}
function closeMobileMenu() {
  document.getElementById('mobileMenu').classList.remove('open');
  document.getElementById('hamburger').classList.remove('open');
}

// ===== NAVBAR SCROLL =====
window.addEventListener('scroll', () => {
  document.getElementById('navbar').classList.toggle('scrolled', window.scrollY > 40);
});

// ===== INTERSECTION OBSERVER (fade-up) =====
let observer;
function observeFadeUps() {
  if (observer) observer.disconnect();
  observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        entry.target.classList.add('visible');
        observer.unobserve(entry.target);
      }
    });
  }, { threshold: 0.12 });
  document.querySelectorAll('.fade-up:not(.visible)').forEach(el => observer.observe(el));
}

// ===== CAROUSEL =====
function updateCarousel() {
  const track = document.getElementById('carouselTrack');
  if (!track) return;
  track.style.transform = `translateX(-${carouselIndex * 100}%)`;
  document.querySelectorAll('.carousel-dot').forEach((dot, i) => {
    dot.classList.toggle('active', i === carouselIndex);
  });
}
function nextSlide() {
  const slides = document.querySelectorAll('.quote-slide');
  carouselIndex = (carouselIndex + 1) % slides.length;
  updateCarousel();
  resetCarouselTimer();
}
function prevSlide() {
  const slides = document.querySelectorAll('.quote-slide');
  carouselIndex = (carouselIndex - 1 + slides.length) % slides.length;

