.section-label {
  font-family: var(--body);
  font-size: 13px;
  font-weight: 600;
  color: var(--gold);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.section-title {
  font-family: var(--display);
  font-size: clamp(28px, 4vw, 40px);
  font-weight: 700;
  color: var(--fg);
  line-height: 1.25;
  margin-bottom: 8px;
}
.section-title-en {
  font-family: var(--display);
  font-size: clamp(18px, 2.5vw, 24px);
  font-weight: 400;
  color: var(--secondary);
  line-height: 1.4;
  margin-bottom: 32px;
}
.gold-line {
  width: 60px; height: 2px;
  background: linear-gradient(90deg, var(--gold), transparent);
  margin: 20px 0;
}
.gold-line.center { margin: 20px auto; }
.container {
  max-width: var(--max-w);
  margin: 0 auto;
  padding: 0 24px;
}
.section-pad { padding: 96px 0; }

/* Fade-in animation */
.fade-up {
  opacity: 0;
  transform: translateY(32px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}
.fade-up.delay-1 { transition-delay: 0.1s; }
.fade-up.delay-2 { transition-delay: 0.2s; }
.fade-up.delay-3 { transition-delay: 0.3s; }
.fade-up.delay-4 { transition-delay: 0.4s; }

/* Card hover */
.hover-card {
  background: var(--card);
  border: 1px solid var(--gold-border);
  border-radius: 8px;
  padding: 32px;
  transition: transform 0.3s, border-color 0.3s, box-shadow 0.3s;
}
.hover-card:hover {
  transform: translateY(-6px);
  border-color: var(--gold);
  box-shadow: 0 12px 40px rgba(200,162,75,0.15);
}

/* Buttons */
.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--sand);
  color: var(--bg);
  font-family: var(--body);
  font-size: 15px;
  font-weight: 700;
  padding: 14px 32px;
  border-radius: 4px;
  letter-spacing: 0.06em;
  transition: background 0.2s, transform 0.2s;
}
.btn-primary:hover { background: #e8924a; transform: translateY(-2px); }
.btn-outline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: transparent;
  color: var(--fg);
  font-family: var(--body);
  font-size: 15px;
  font-weight: 600;
  padding: 13px 30px;
  border-radius: 4px;
  border: 1.5px solid var(--gold);
  letter-spacing: 0.06em;
  transition: background 0.2s, color 0.2s, transform 0.2s;
}
.btn-outline:hover { background: var(--gold); color: var(--bg); transform: translateY(-2px); }

