function addSection(){
  var name = prompt('新分類的標題？');
  if (name === null || name.trim() === '') return;
  name = name.trim();
  var key = 'custom' + Date.now();

  var block = document.createElement('div');
  block.className = 'section-block';
  block.innerHTML =
    '<div class="section-title" data-section="' + key + '">' +
      '<span class="toggle-arrow" title="收合/展開">▼</span>' +
      '<span class="idx">、</span>' +
      '<span class="title-text" contenteditable="true" spellcheck="false">' + name.replace(/</g, '&lt;') + '</span> ' +
      '<span class="count">0項</span>' +
      '<span class="section-del" title="刪除整個分類">🗑</span>' +
    '</div>' +
    '<div class="grid" data-section="' + key + '"></div>' +
    '<button class="btn-add-item" data-section="' + key + '">+ 新增項目</button>';
  document.querySelector('.wrap').appendChild(block);
  wireSectionBlock(block);
  renumberSections();
  saveTitles();
  toast('已新增「' + name + '」分類，接著可以按「+ 新增項目」加內容');
}

function applyLayout(){
  var layout = loadLayout();
  if (!layout) return;
  var allItems = {};
  document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
  document.querySelectorAll('.grid').forEach(function(grid){
    var ids = layout[grid.dataset.section];
    if (!ids) return;
    ids.forEach(function(id){
      if (allItems[id]) grid.appendChild(allItems[id]);
    });
  });
}

function getDragAfterElement(grid, y){
  var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
  return els.reduce(function(closest, child){
    var box = child.getBoundingClientRect();
    var offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) {
      return { offset: offset, element: child };
    }
    return closest;
  }, { offset: -Infinity, element: null }).element;
}

// 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
// .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
// 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
// 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
// drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
// 拖放機制，也就不會有這個衝突。
var dragEl = null;
var sourceGrid = null;

function onMouseMove(e){
  if (!dragEl) return;
  var el = document.elementFromPoint(e.clientX, e.clientY);
  var targetGrid = el ? el.closest('.grid') : null;
  if (!targetGrid) return;
  var afterEl = getDragAfterElement(targetGrid, e.clientY);
  if (afterEl == null) {
    targetGrid.appendChild(dragEl);
  } else if (afterEl !== dragEl) {
    targetGrid.insertBefore(dragEl, afterEl);
  }
}

