var TITLES_KEY = 'coach888_titles';
var BADGES_KEY = 'coach888_badges';
var COLLAPSE_KEY = 'coach888_collapse';
var NAMES_KEY = 'coach888_names';
var CHINESE_NUM = ['一','二','三','四','五','六','七','八','九','十','十一','十二','十三','十四','十五','十六','十七','十八','十九','二十'];

