var SYNC_ENDPOINT = 'https://event.bymyway.com/api/coach888/state';
var _syncTimer = null;
function syncStateToServer(){
  clearTimeout(_syncTimer);
  _syncTimer = setTimeout(function(){
    var payload = {};
    [LAYOUT_KEY, TITLES_KEY, BADGES_KEY, NAMES_KEY, COLLAPSE_KEY].forEach(function(k){
      var v = localStorage.getItem(k);
      if (v != null) payload[k] = v;
    });
    fetch(SYNC_ENDPOINT, {
      method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload)
    }).catch(function(){});
  }, 400);
}
function pullStateFromServer(){
  return fetch(SYNC_ENDPOINT).then(function(r){ return r.json(); }).then(function(state){
    [LAYOUT_KEY, TITLES_KEY, BADGES_KEY, NAMES_KEY, COLLAPSE_KEY].forEach(function(k){
      if (state[k] != null) localStorage.setItem(k, state[k]);
    });
  }).catch(function(){});
}

function renumber(grid){
  grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
  var title = grid.previousElementSibling;
  if (title && title.classList.contains('section-title')) {
    var countEl = title.querySelector('.count');
    if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
  }
}

function saveLayout(){
  var layout = {};
  document.querySelectorAll('.grid').forEach(function(grid){
    layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
  });
  localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
  // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
  document.querySelectorAll('.grid').forEach(function(grid){
    localStorage.removeItem('coach888_order_' + grid.dataset.section);
  });
  syncStateToServer();
}

function loadLayout(){
  var raw = localStorage.getItem(LAYOUT_KEY);
  if (raw) {
    try { return JSON.parse(raw); } catch(e){}
  }
  // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
  var legacy = {}, found = false;
  document.querySelectorAll('.grid').forEach(function(grid){
    var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
    if (old) {
      try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
    }
  });
  return found ? legacy : null;
}

