(function initRecycleBin(){
  var block = document.getElementById('recycleBinBlock');
  if (!block) return;
  var arrow = block.querySelector('.toggle-arrow');
  arrow.addEventListener('click', function(){
    block.classList.toggle('collapsed');
    saveCollapse();
  });
  var emptyBtn = document.getElementById('btnEmptyRecycleBin');
  emptyBtn.addEventListener('click', function(){
    var grid = block.querySelector('.grid');
    var n = grid.querySelectorAll('.item').length;
    if (n === 0) { toast('最近刪除目前是空的'); return; }
    if (!confirm('確定要永久清空「最近刪除」的 ' + n + ' 個項目嗎？這個動作無法復原。')) return;
    grid.innerHTML = '';
    renumber(grid);
    saveLayout();
    toast('已永久清空最近刪除');
  });
})();

