function wireSectionBlock(block){
  var title = block.querySelector('.section-title');
  var grid = block.querySelector('.grid');
  var arrow = title.querySelector('.toggle-arrow');
  arrow.addEventListener('click', function(){
    block.classList.toggle('collapsed');
    saveCollapse();
  });
  var delBtn = title.querySelector('.section-del');
  delBtn.addEventListener('click', function(){
    var name = title.querySelector('.title-text').textContent.trim();
    if (!confirm('確定要刪除整個「' + name + '」分類嗎？裡面的項目會先移到「最近刪除」，分類本身會消失。')) return;
    var recycleGrid = document.querySelector('.grid[data-section="recentlydeleted"]');
    var items = Array.prototype.slice.call(grid.querySelectorAll('.item'));
    items.forEach(function(it){ recycleGrid.appendChild(it); });
    renumber(recycleGrid);
    block.remove();
    renumberSections();
    saveLayout();
    saveTitles();
    toast('已刪除「' + name + '」分類，' + items.length + ' 個項目已移到「最近刪除」');
