// 2026-09-04修復：「➕新增分類」建出來的分類原本只活在當下這個瀏覽器分頁的記憶體裡，
// 沒有存進任何地方（不是localStorage結構、不是伺服器、更不是原始HTML檔案）——
// 教練回報「新增分類後，批量搬移的下拉選單找不到新分類」，根因就是這個：分類本身
// 隨時可能消失，下拉選單只是最先被發現的症狀。現在把「有哪些自訂分類＋標題」也存進
// SECTIONS_KEY並跟著跨裝置同步，重新整理或換裝置都能重建出同一批空分類殼。
function saveSections(){
  var sections = [];
  document.querySelectorAll('.section-title').forEach(function(t){
    if (t.dataset.section.indexOf('custom') === 0) {
      var span = t.querySelector('.title-text');
      sections.push({ key: t.dataset.section, name: span ? span.textContent.trim() : '' });
    }
  });
  localStorage.setItem(SECTIONS_KEY, JSON.stringify(sections));
  syncStateToServer();
}

function createSectionBlock(key, name){
  var block = document.createElement('div');
  block.className = 'section-block';
  block.innerHTML =
    '<div class="section-title" data-section="' + key + '">' +
      '<span class="toggle-arrow" title="收合/展開">▼</span>' +
      '<span class="idx">、</span>' +
      '<span class="title-text" contenteditable="true" spellcheck="false">' + name.replace(/</g, '&lt;') + '</span> ' +
      '<span class="count">0項</span>' +
      '<span class="section-del" title="刪除整個分類">🗑</span>' +
    '</div>' +
    '<div class="grid" data-section="' + key + '"></div>' +
    '<button class="btn-add-item" data-section="' + key + '">+ 新增項目</button>';
  return block;
}

function restoreCustomSections(){
  var raw = localStorage.getItem(SECTIONS_KEY);
  if (!raw) return;
  try {
    var sections = JSON.parse(raw);
    sections.forEach(function(s){
      if (document.querySelector('.section-title[data-section="' + s.key + '"]')) return; // 已存在(靜態或先前已重建)，不重複建立
      var block = createSectionBlock(s.key, s.name || '未命名分類');
      document.querySelector('.wrap').appendChild(block);
    });
    renumberSections();
  } catch(e){}
}

function wireAllSectionBlocks(){
  document.querySelectorAll('.section-block').forEach(function(block){
    if (block.id === 'recycleBinBlock' || block.dataset.wired) return;
    wireSectionBlock(block);
    block.dataset.wired = '1';
  });
}

