        state = {k: None for k in COACH888_STATE_KEYS}
        for r in rows:
            if r["key"] in COACH888_STATE_KEYS:
                state[r["key"]] = r["value"]
        return Response(
            json.dumps(state), status=200, headers={**resp_headers, "Content-Type": "application/json"},
