  handle.addEventListener('mousedown', function(e){
    e.preventDefault();
    dragEl = item;
    sourceGrid = item.closest('.grid');
    item.classList.add('dragging');
    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup', onMouseUp);
  });
  var del = item.querySelector('.item-del');
  del.addEventListener('click', function(){
    var name = item.querySelector('.name').textContent.trim();
    var grid = item.closest('.grid');
    if (grid.dataset.section === 'recentlydeleted') {
      // 在「最近刪除」裡按刪除＝真的永久刪除，才需要確認
      if (!confirm('確定要永久刪除「' + name + '」嗎？這個動作無法復原。')) return;
      item.remove();
      renumber(grid);
      saveLayout();
      toast('已永久刪除「' + name + '」');
      return;
    }
    // 一般分類刪除＝移進「最近刪除」，可復原，不用再跳確認視窗
    var recycleGrid = document.querySelector('.grid[data-section="recentlydeleted"]');
    recycleGrid.appendChild(item);
    renumber(grid);
    renumber(recycleGrid);
    saveLayout();
    toast('已移到「最近刪除」，用☑️批量搬移模式可以勾選移回原分類');
  });
  var badgeEl = item.querySelector('.badge');
  bindEditable(badgeEl, saveBadges);
  ensureBulkCheckbox(item);
  ensureEditIcon(item);
}

