// 2026-09-04教練交辦：大分類(整個section-block)本身也要能拖曳調整順序，收合起來時尤其常用。
// 跟item拖曳同樣手刻mousedown/mousemove/mouseup，但用document.elementFromPoint找出游標
// 底下是哪個section-block，再依那個block自己的垂直中點判斷插在它前面還是後面——.wrap用
// CSS column-count雙欄排版，不是單純上下一直排，所以不能像item那樣對整個容器內所有元素
// 做一次性Y座標比較，要用「當下游標實際壓在哪一塊」來判斷才會跟畫面看到的位置一致。
var sectionDragEl = null;

function onSectionMouseMove(e){
  if (!sectionDragEl) return;
  var el = document.elementFromPoint(e.clientX, e.clientY);
  var targetBlock = el ? el.closest('.section-block') : null;
  if (!targetBlock || targetBlock === sectionDragEl || targetBlock.id === 'recycleBinBlock') return;
  var wrap = document.querySelector('.wrap');
  var box = targetBlock.getBoundingClientRect();
  var before = e.clientY < box.top + box.height / 2;
  if (before) {
    wrap.insertBefore(sectionDragEl, targetBlock);
  } else {
    wrap.insertBefore(sectionDragEl, targetBlock.nextElementSibling);
  }
}

function onSectionMouseUp(){
  if (!sectionDragEl) return;
  sectionDragEl.classList.remove('section-dragging');
  sectionDragEl = null;
  saveSectionOrder();
  document.removeEventListener('mousemove', onSectionMouseMove);
  document.removeEventListener('mouseup', onSectionMouseUp);
}

function saveSectionOrder(){
  var order = Array.prototype.map.call(document.querySelectorAll('.section-block'), function(b){
    var t = b.querySelector('.section-title');
    return t ? t.dataset.section : null;
  }).filter(Boolean);
  localStorage.setItem(SECTION_ORDER_KEY, JSON.stringify(order));
  syncStateToServer();
}

function applySectionOrder(){
  var raw = localStorage.getItem(SECTION_ORDER_KEY);
  if (!raw) return;
  try {
    var order = JSON.parse(raw);
    var wrap = document.querySelector('.wrap');
    order.forEach(function(key){
      var t = document.querySelector('.section-title[data-section="' + key + '"]');
      if (t) wrap.appendChild(t.closest('.section-block'));
    });
  } catch(e){}
}

restoreCustomSections(); // 先把本機記得的自訂分類殼補回來，applyLayout才有地方可以放項目

