window.fetch = function(){ return Promise.resolve({ json: () => Promise.resolve({}), ok: true }); };
'fetch blocked, safe to test now';

// collapse all sections first, matching coach's stated use case
document.querySelectorAll('.section-block').forEach(b => { if (b.id !== 'recycleBinBlock') b.classList.add('collapsed'); });

function rectMid(el){ const r = el.getBoundingClientRect(); return { x: r.left + r.width/2, y: r.top + r.height/2 }; }

// drag "houtai" (2nd) down to just after "bugongkai" (6th)
const houtaiBlock = document.querySelector('.section-title[data-section="houtai"]').closest('.section-block');
const handle = houtaiBlock.querySelector('.section-drag-handle');
const targetBlock = document.querySelector('.section-title[data-section="bugongkai"]').closest('.section-block');
const targetRect = targetBlock.getBoundingClientRect();

handle.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, clientX: rectMid(handle).x, clientY: rectMid(handle).y }));
// move to just below bugongkai's midpoint -> should insert AFTER it
document.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: targetRect.left + 10, clientY: targetRect.bottom - 2 }));
document.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));

const after = [...document.querySelectorAll('.section-title')].map(t => t.dataset.section);
JSON.stringify(after);

const targetBlock = document.querySelector('.section-title[data-section="bugongkai"]').closest('.section-block');
const r = targetBlock.getBoundingClientRect();
const el = document.elementFromPoint(r.left + 10, r.bottom - 2);
JSON.stringify({ rect: r, elTag: el ? el.tagName : null, elClass: el ? el.className : null, closestBlock: el ? (el.closest('.section-block') ? el.closest('.section-block').querySelector('.section-title').dataset.section : null) : null });

