// Viewport is 0x0 here (background pane), so pixel-geometry (elementFromPoint/getBoundingClientRect)
// won't work reliably. Test the mousedown->[manual DOM move]->mouseup workflow + persistence directly,
// trusting the geometry math itself since it's the same proven pattern as the existing item-drag feature.
const wrap = document.querySelector('.wrap');
const houtaiBlock = document.querySelector('.section-title[data-section="houtai"]').closest('.section-block');
const handle = houtaiBlock.querySelector('.section-drag-handle');
