handle.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
const draggingNow = houtaiBlock.classList.contains('section-dragging');

// simulate what onSectionMouseMove would do given "after bugongkai"
wrap.insertBefore(houtaiBlock, bugongkaiBlock.nextElementSibling);

document.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));
const draggingAfterUp = houtaiBlock.classList.contains('section-dragging');

const order = [...document.querySelectorAll('.section-title')].map(t => t.dataset.section);
